import { ASSISTANT_OPERATIONS } from "./catalog";
import type { ManualProcedure } from "./manual-guide-procedures";

// Exact operation bindings prevent a guide for one action from leaking into a
// different action that happens to share the same endpoint.
export const SUPPLEMENTAL_GUIDES: Array<ManualProcedure & { operationIds: string[] }> = [];
function guide(ids: string, file: string, controls: string[], ...steps: string[]) {
  const operationIds = ids.split(" ");
  for (const id of operationIds) if (!ASSISTANT_OPERATIONS.some(op => op.id === id)) throw new Error(`Unknown manual guide operation: ${id}`);
  const operations = ASSISTANT_OPERATIONS.filter(op => operationIds.includes(op.id));
  const escape = (v: string) => v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  SUPPLEMENTAL_GUIDES.push({ id: `manual:${operationIds[0]}`, operationIds,
    method: [...new Set(operations.map(op => op.method))].join("|"),
    path: new RegExp(`^(?:${[...new Set(operations.map(op => escape(op.path)))].join("|")})$`),
    evidence: controls.map(contains => ({ file, contains })), steps });
}
