guide("retail.after-sale.list", retail + "pages/RetailReturnsPage.tsx", ["retailAfterSalesApi.list"], "Mở danh sách hậu mãi/đổi trả tại chi nhánh, lọc thời gian và loại chứng từ cần xem. Đối chiếu đơn gốc, hàng, số tiền hoàn/thu mua và trạng thái. Không tạo chứng từ mới để kiểm tra lịch sử.");
guide("retail.points.policy.get retail.points.customer.search api.get.47d83644d10887c0", retail + "components/coupons/RetailPointsPanel.tsx", ["Chính sách điểm thưởng", "Sổ điểm khách hàng"], "Mở Ưu đãi → Điểm thưởng. Xem Chính sách điểm thưởng; để xem sổ điểm, tìm và chọn đúng khách hàng rồi đối chiếu số dư cùng từng phát sinh theo thời gian, loại và lý do. Không lưu chính sách hoặc điều chỉnh điểm khi chỉ tra cứu.");
guide("api.post.6c5a8520aa90cc8e", retail + "components/coupons/RetailPointsPanel.tsx", ["Điểm (+/-)", "Điều chỉnh"], "Mở Ưu đãi → Điểm thưởng → Sổ điểm khách hàng, tìm đúng khách hàng. Nhập số điểm tăng hoặc giảm và lý do; kiểm tra dấu của số điểm trước khi chọn Điều chỉnh.", "Đối chiếu số dư mới và dòng phát sinh trong sổ điểm. Nếu chưa rõ kết quả, tải lại sổ điểm trước khi điều chỉnh lần nữa.");
guide("retail.finance.cashbook.reconcile", retail + "pages/RetailFinancePage.tsx", ["Sổ quỹ", "Đối soát ca tiền mặt"], "Mở Tài chính → Sổ quỹ, chọn Từ ngày và Đến ngày. Đọc tiền mặt/ngân hàng ròng, từng phát sinh và Đối soát ca tiền mặt; đối chiếu dự kiến, kiểm đếm và chênh lệch. Không chọn Chốt kỳ hoặc tạo phiếu khi chỉ xem đối soát.");
guide("api.get.070d48d67bb5ed90", retail + "pages/RetailFinancePage.tsx", ["Lãi lỗ", "Giá vốn đã biết"], "Mở Tài chính → Lãi lỗ, chọn khoảng ngày và chi nhánh. Xem doanh thu, giá vốn đã biết, lãi gộp, chi phí và lãi ròng. Kiểm tra dòng Thiếu dữ liệu; không coi số lãi là đầy đủ nếu chưa có giá vốn.");
guide("api.get.78da159ec226e07e api.get.7c1d9c9cda4722a9", retail + "pages/RetailFinancePage.tsx", ["Hoa hồng", "Chọn CTV"], "Mở Tài chính → Hoa hồng, chọn khoảng ngày để xem tổng hợp CTV. Muốn xem sao kê, chọn đúng CTV rồi đối chiếu phát sinh, khoản đảo, đã chi trả và số dư. Không ghi chi trả hoặc đối soát lại khi chỉ tra cứu.");
guide("api.post.9102a0fae468bcab", retail + "pages/RetailFinancePage.tsx", ["Đối soát phát sinh"], "Mở Tài chính → Hoa hồng, chọn CTV và khoảng ngày. Đối chiếu chứng từ nguồn rồi chọn Đối soát phát sinh. Chờ thông báo hoàn tất và xem lại các dòng hoa hồng/khoản đảo cùng số dư; bước này chưa chi trả cho đối tác.");
guide("api.post.3c5a416752fe6656", retail + "pages/RetailFinancePage.tsx", ["Số tiền chi trả", "Ghi chi trả"], "Mở Tài chính → Hoa hồng, chọn đúng CTV, xem số dư và khoản đã chi. Nhập Số tiền chi trả, chọn Quỹ chi và lý do/tham chiếu theo biểu mẫu rồi kiểm tra lại.", "Chọn Ghi chi trả; đối chiếu phát sinh chi và số dư sau lưu. Đây là ghi nhận chứng từ chi trả, không phải lệnh ngân hàng tự chuyển tiền. Khi kết quả chưa rõ, kiểm tra sao kê trước khi ghi lại.");
guide("retail.partner.supplier.list retail.partner.user.list retail.partner.customer.list", retail + "pages/RetailPartnersPage.tsx", ["/retail/partners/suppliers", "/retail/partners/users", "/retail/partners/customers"], "Mở biểu mẫu thêm/sửa đối tác với quyền quản lý. Xem danh sách chọn nhà cung cấp, tài khoản nhân viên hoặc khách hàng liên kết theo vai trò cần tra cứu. Tìm đúng tên/mã, rồi đóng biểu mẫu khi chỉ xem danh sách; không lưu đối tác mới.");
guide("api.get.9ca47ce89d0dd0f0", retail + "pages/RetailPartnersPage.tsx", ["/retail/partners/me"], "Đăng nhập tài khoản được liên kết đối tác, mở Đối tác bán lẻ. Với tài khoản không có quyền đọc danh sách quản lý, màn hình tải hồ sơ đối tác của chính tài khoản. Đối chiếu mã, tên và vai trò; nếu quản trị viên cần xem người khác, dùng danh sách đối tác, không đổi liên kết tài khoản.");
guide("api.get.203a9f8e9a785680", retail + "components/RetailPartnerStatement.tsx", ["Sao kê hoa hồng của tôi"], "Mở Đối tác bán lẻ bằng tài khoản đối tác, xem Sao kê hoa hồng của tôi. Chọn Từ ngày/Đến ngày, đối chiếu chứng từ, hoa hồng, chi trả và số dư. Báo cáo này thuộc đối tác gắn với tài khoản đang đăng nhập.");
guide("retail.partner.commission.policy.list", retail + "components/RetailCommissionPoliciesPanel.tsx", ["Chính sách"], "Mở Đối tác bán lẻ → Chính sách, xem chính sách chung và chính sách áp dụng cho CTV. Đối chiếu thời gian hiệu lực, mức hoa hồng và phạm vi; không lưu thay đổi khi chỉ tra cứu.");
guide("api.get.d9daa6226ed98e83", retail + "components/RetailProductCommissionsPanel.tsx", ["Hoa hồng sản phẩm", "Lọc cấu hình SKU"], "Mở Đối tác bán lẻ → Hoa hồng sản phẩm. Tìm nhóm, sản phẩm hoặc SKU, lọc Có mức riêng/Chính sách chung rồi mở rộng cây để xem mức đang áp dụng. Không chọn Lưu cấu hình khi chỉ xem.");
guide("quotation.quote.recalculate", "src/modules/quotation/EstimateRegeneration.tsx", ["Tạo lại dự toán từ câu trả lời"], "Mở bản nháp dự toán, trả lời ít nhất một câu hỏi bổ sung và lưu các thay đổi khác trước. Chọn Tạo lại dự toán từ câu trả lời, đọc tác động và xác nhận; thao tác dùng lượt AI.", "Đối chiếu hạng mục, số lượng và các sản phẩm cần bổ sung giá sau xử lý. Không coi bản tính lại là đã được duyệt.");
guide("quotation.estimate.create", "src/modules/quotation/App.tsx", ["const createQuote = async () =>", "Đang tạo bản nháp báo giá"], "Nếu biểu mẫu lập dự toán đang giữ yêu cầu đã phân tích nhưng chưa tạo được chứng từ, kiểm tra khách hàng, hạng mục và số lượng đã chọn rồi dùng nút tạo báo giá/dự toán của biểu mẫu.", "Chờ lưu và tạo file theo mẫu; nếu file lỗi nhưng chứng từ đã lưu, mở chứng từ đó để xử lý file, không tạo thêm dự toán. Nếu không có phiên yêu cầu đã phân tích, không phân tích lại rồi mặc định đó là cùng yêu cầu cũ.");
const quotation = "src/modules/quotation/";
guide("quotation.catalog.duplicate", quotation + "CatalogProductDialog.tsx", ["sourceUpdatedAt", "duplicate"], "Trong Bảng giá, tìm sản phẩm nguồn → Thao tác → Nhân bản. Nhập mã mới và kiểm tra tên, đơn vị, giá, thuộc tính cùng thời gian áp dụng; lưu bản sao rồi tìm lại bằng mã mới. Không sửa sản phẩm nguồn.");
guide("quotation.catalog.delete", quotation + "CatalogBulkDialog.tsx", ["Xem trước thay đổi", "Xác nhận {items.length} sản phẩm"], "Trong Bảng giá, chọn Xóa tại đúng sản phẩm. Xem trước thay đổi, kiểm tra chỉ sản phẩm cần xóa được chọn rồi xác nhận. Mở bộ lọc đã xóa để đối chiếu; đây là thao tác xóa qua quy trình xem trước của danh mục.");
guide("quotation.catalog.restore", quotation + "PriceListPanel.tsx", ["Khôi phục", "statusFilter === \"deleted\""], "Trong Bảng giá, lọc sản phẩm đã xóa, tìm đúng mã rồi chọn Khôi phục. Xem trước thay đổi và xác nhận đúng sản phẩm; quay lại danh sách đang dùng để kiểm tra trạng thái khôi phục.");
guide("quotation.price-list.list", quotation + "PriceListPanel.tsx", ["Tài liệu đã nạp", "Xem file"], "Mở Bảng giá → Tài liệu đã nạp. Đọc tên file nguồn, ngày, số sản phẩm và dòng bỏ qua; dùng Xem file để đối chiếu. Không nhập lại file chỉ để xem lịch sử.");
guide("quotation.template.list", quotation + "QuoteTemplate.tsx", ["Loại mẫu tài liệu", "Xem thêm mẫu khác"], "Mở Mẫu tài liệu, chọn loại báo giá/dự toán/hợp đồng/nghiệm thu/quyết toán, tìm theo tên hoặc định dạng. Xem trước mẫu và tải thêm trang nếu cần; không coi danh sách trang đầu là toàn bộ mẫu.");
guide("quotation.template.update", quotation + "QuoteTemplate.tsx", ["Chuyển nhóm"], "Tìm đúng mẫu tài liệu, chọn Chuyển nhóm và chọn loại tài liệu đích. Kiểm tra nhóm mới trong danh sách sau khi lưu; thao tác đổi nhóm không sửa nội dung file mẫu.");
guide("quotation.template.delete", quotation + "QuoteTemplate.tsx", ["Xóa mẫu này"], "Tìm đúng mẫu, xem trước để đối chiếu rồi chọn Xóa mẫu này. Đọc xác nhận, đồng ý khi đúng mẫu và kiểm tra danh sách/hạn mức sau xử lý; không xóa mẫu khác nếu bị từ chối do đang sử dụng.");
guide("quotation.template.download", quotation + "QuoteTemplate.tsx", ["Tải file mẫu về máy"], "Chọn đúng loại và mẫu, dùng Tải file mẫu về máy. Kiểm tra tên/định dạng và mở file tải về; tải mẫu không tạo chứng từ mới.");
guide("quotation.customer-quote.suggest", quotation + "CustomerQuotes.tsx", ["Gợi ý sản phẩm bằng AI"], "Trong Tạo báo giá khách, chọn AI gợi ý, nhập mô tả sản phẩm/hạng mục cần tìm rồi Gợi ý sản phẩm bằng AI. Đọc mục khớp bảng giá và mục chưa có, chỉnh yêu cầu nếu thiếu thông tin.", "Dừng sau phần gợi ý nếu chưa được yêu cầu tạo báo giá; không bấm Tạo báo giá. Chức năng này cần dịch vụ AI và hạn mức, nên không thay được lỗi nhà cung cấp AI đang ngừng hoạt động.");
guide("quotation.quote.export-retry", quotation + "CustomerProductListDetail.tsx", ["Thử tạo lại file"], "Mở đúng báo giá khách có file tạo lỗi, kiểm tra không có tiến trình đang chạy rồi chọn Thử tạo lại file. Chờ kết quả và tải file được lưu; không tạo lại báo giá để thay tạo lại file.");
guide("quotation.quote.delete", quotation + "App.tsx", ["method: \"DELETE\""], "Trong danh sách báo giá/dự toán, tìm đúng mã và chọn xóa. Đọc nội dung xác nhận cùng trạng thái chứng từ trước khi đồng ý; kiểm tra danh sách sau xử lý. Nếu chứng từ không cho xóa, giữ nguyên lý do, không xóa các chứng từ liên quan để vượt điều kiện.");
guide("quotation.quote.export", quotation + "App.tsx", ["Tạo và tải file mới", "Tải file đã lưu"], "Mở dự toán, lưu hết thay đổi và kiểm tra nội dung/mẫu. Chọn Tải file đã lưu nếu còn đúng phiên bản; nếu chưa có hoặc đã cũ, chọn Tạo và tải file mới theo quyền AI.", "Chờ tạo hoàn tất, kiểm tra tên file và mở đối chiếu mã, khách hàng, tổng tiền. Xuất file nháp không làm chứng từ thành đã duyệt.");
guide("quotation.budget.export", quotation + "BudgetPlanner.tsx", ["Tạo file mới bằng AI", "Tải file đã lưu"], "Mở đúng phương án ngân sách và phần xuất file, kiểm tra mẫu được chọn. Tải file đã lưu nếu phù hợp hoặc Tạo file mới bằng AI khi cần bản mới; chờ hoàn tất rồi mở file đối chiếu phương án và số liệu.");
guide("quotation.contract.export", quotation + "ContractWorkflow.tsx", ["Tùy chọn file hợp đồng", "Tạo và tải file"], "Mở Hợp đồng, chọn đúng hồ sơ, lưu nội dung và kiểm tra Tùy chọn file hợp đồng. Chọn Tải file nếu đã có hoặc Tạo và tải file; chờ hoàn tất và đối chiếu hợp đồng tải về. Không ký hợp đồng chỉ để tải file.");
guide("quotation.acceptance.export", quotation + "ContractWorkflow.tsx", ["Tạo file từ bản đã lưu"], "Mở Chứng từ → Nghiệm thu và đúng hồ sơ. Lưu biên bản trước, chọn Tải file đã có hoặc Tạo file từ bản đã lưu. Mở file kiểm tra khối lượng/ngày/số tiền; tạo file không đồng nghĩa hoàn tất nghiệm thu.");
guide("quotation.file.list quotation.file.download", quotation + "QuotationSettings.tsx", ["Tài liệu đã lưu", "Tải tài liệu"], "Mở Cài đặt Báo giá → Tài liệu đã lưu, tìm đúng tên tài liệu và chọn Tải tài liệu khi cần. Kiểm tra file tải xuống; không nạp lại hoặc tạo thêm chứng từ để lấy file cũ.");
guide("quotation.export.latest", quotation + "CustomerProductListDetail.tsx", ["Đang kiểm tra file đã lưu…"], "Mở đúng chứng từ nguồn và xem trạng thái file đang kiểm tra/đang tạo/đã lưu. Khi có file, kiểm tra tên và phiên bản trước khi tải; không dùng Thử tạo lại file chỉ để hỏi tiến độ.");
guide("api.get.f571d5d6bb5d51ab api.get.03a093fc9349a692 api.get.c611407da8136c5f api.get.614b2375b202f4b6", "src/pages/AnalyticsTab.tsx", ["Tổng doanh thu", "Tuổi công nợ học phí", "Chi phí theo dòng tiền"], "Dùng tài khoản quản trị mở Phân tích & Báo cáo, chọn khoảng ngày, chi nhánh và khóa học nếu cần. Đọc Tổng doanh thu/Cơ cấu doanh thu, Tuổi công nợ học phí hoặc Chi phí theo dòng tiền đúng phần yêu cầu.", "Kiểm tra phạm vi và các dòng chưa được tính vào báo cáo. Tuổi công nợ học phí trên màn hình tính từ ngày gửi thông báo, không mặc định là số ngày quá hạn hợp đồng.");
guide("api.post.c1af6a4524808fc9", "src/pages/AnalyticsTab.tsx", ["Ghi nhận chi phí vận hành", "Thêm khoản chi"], "Trong Phân tích & Báo cáo → Ghi nhận chi phí vận hành, nhập nhóm chi phí, nội dung, số tiền, ngày và chi nhánh phù hợp. Đối chiếu khoản chi chưa được ghi rồi chọn Thêm khoản chi.", "Kiểm tra thông báo và tổng chi phí trong đúng kỳ; khoản xác nhận được tính ngay vào chi phí và kết quả vận hành.");
guide("finance.treasury.vouchers.create", "src/modules/finance/pages/TreasuryPage.tsx", ["/treasury/vouchers", "Quỹ nhận"], "Trong Sổ quỹ & dòng tiền → Phiếu thu / chi, chọn lập phiếu thu, chi hoặc chuyển quỹ đúng yêu cầu. Chọn quỹ/tài khoản, quỹ nhận nếu chuyển, nhập số tiền, ngày ghi sổ, nội dung và tham chiếu.", "Kiểm tra dữ liệu rồi lưu phiếu; đối chiếu trạng thái Chờ duyệt. Số dư chỉ thay đổi khi được duyệt; không dùng phiếu quỹ để ghi trùng giao dịch đã thu/chi ở chứng từ nguồn.");
const repair = "src/modules/repair/";
guide("api.post.951d43982cb708bc", repair + "RepairBoardPage.tsx", ["Chuyển bước tiếp", "Lịch sử xử lý"], "Tìm đúng phiếu sửa chữa, đọc trạng thái và điều kiện bước kế tiếp. Chọn Chuyển bước tiếp hoặc hành động trạng thái có trên phiếu; bổ sung kỹ thuật viên/ghi chú khi được hỏi rồi xác nhận.", "Kiểm tra cột trạng thái và Lịch sử xử lý. Nếu bước mong muốn không có trên phiếu, không dùng bàn giao/hủy để thay thế bước đó.");
guide("api.post.572b64fca460dafc", repair + "RepairBoardPage.tsx", ["Bàn giao", "Thu tiền để bàn giao"], "Mở phiếu đã hoàn tất, đối chiếu thiết bị, khách hàng và công nợ. Chọn Bàn giao khi đủ điều kiện; nếu cần thu tiền, xử lý đúng khoản thu được yêu cầu trước, không tự bỏ qua công nợ.", "Kiểm tra trạng thái Đã giao và lịch sử bàn giao; không xác nhận khi thiết bị chưa thực sự giao cho khách.");
guide("api.post.ad54adfbaa37674b", repair + "RepairBoardPage.tsx", ["Số tiền thu", "Ghi nhận thanh toán"], "Mở đúng phiếu và kiểm tra Đối soát thanh toán trước. Nhập Số tiền thu thực tế rồi chọn Ghi nhận thanh toán; đối chiếu khoản đã thu và còn lại.", "Nếu chưa rõ lần trước đã lưu chưa, xem đối soát trước khi thu tiếp; không đổi số tiền hoặc tạo khoản thu mới để vượt cảnh báo giao dịch đang chờ xác minh.");
guide("api.get.8cb8202ecb5a1164", repair + "RepairPaymentSummary.tsx", ["Đối soát thanh toán", "Sổ thu đang lệch với phiếu sửa"], "Mở đúng phiếu → Đối soát thanh toán. Xem từng lần thu, tổng Đã thu/Còn lại và kết quả khớp sổ; nếu lệch, kiểm tra nguồn trước khi thu tiếp. Không bấm Ghi nhận thanh toán khi chỉ đối soát.");
guide("api.get.cd0981c57831ef5c api.get.c5fac63d8679d159", repair + "RepairCarePanel.tsx", ["Lịch sử phiếu này", "Lịch sử khách hàng"], "Mở phiếu → Chăm sóc khách hàng. Xem Lịch sử phiếu này hoặc mở Lịch sử khách hàng để đối chiếu các lần sửa khác; kiểm tra đúng khách và thời điểm, không ghi tương tác mới khi chỉ xem.");
guide("api.post.30630b0bdc49b30c", repair + "RepairCarePanel.tsx", ["Ghi tương tác", "Loại tương tác"], "Trong Chăm sóc khách hàng của đúng phiếu, chọn kênh và loại tương tác Khách gửi/Nhân viên phản hồi/Ghi chú. Nhập nội dung rồi Ghi tương tác; kiểm tra dòng lịch sử mới. Mục này ghi nhận trao đổi, không tự gửi tin cho khách.");
guide("api.post.6fda6d726245dee1", repair + "RepairCarePanel.tsx", ["Lưu trạng thái"], "Trong Chăm sóc khách hàng, chọn Đang xử lý/Chờ phản hồi/Đã xử lý theo yêu cầu rồi Lưu trạng thái. Mở lại để đối chiếu; đây là trạng thái chăm sóc, không thay trạng thái sửa chữa.");
guide("repair.parts.list", repair + "RepairTicketExtras.tsx", ["Vật tư sử dụng"], "Mở đúng phiếu → Vật tư sử dụng. Đọc linh kiện, số lượng, diện chi phí và Đã xuất/Đã hoàn/Đã hủy; phân biệt vật tư thủ công không trừ kho với xuất từ kho. Không xuất/hoàn thêm khi chỉ tra cứu.");
guide("api.post.742b8c7c7d343778", repair + "RepairTicketExtras.tsx", ["Chấm điểm kỹ thuật (tại quầy)", "Lưu đánh giá"], "Mở phiếu → Chấm điểm kỹ thuật (tại quầy), ghi đúng đánh giá khách cung cấp gồm điểm tổng, tiêu chí và nhận xét. Chọn Lưu đánh giá và kiểm tra thông báo đã ghi nhận; không tự đặt điểm thay khách.");
guide("api.get.d2d1a3ba9b169ce6", repair + "RepairTicketExtras.tsx", ["Thông báo đã gửi khách"], "Mở phiếu → Thông báo đã gửi khách, xem sự kiện tiếp nhận/sửa xong và trạng thái gửi/lỗi/bỏ qua. Chỉ đọc lịch sử; không chọn Gửi lại khi chưa có yêu cầu gửi.");
const finance = "src/modules/finance/";
const treasury = finance + "pages/TreasuryPage.tsx";
guide("finance.treasury.accounts.list", treasury, ["Quỹ & tài khoản"], "Trong Sổ quỹ & dòng tiền, chọn Quỹ & tài khoản. Đọc tên quỹ, loại tiền mặt/ngân hàng, số dư đầu kỳ và số dư hiện tại theo chi nhánh đang chọn; không tạo quỹ mới khi chỉ tra cứu.");
guide("finance.treasury.vouchers.list", treasury, ["Phiếu thu / chi"], "Chọn Phiếu thu / chi trong Sổ quỹ & dòng tiền. Đọc ngày, loại, nội dung, số tiền, trạng thái và người duyệt; phân biệt Chờ duyệt với Đã ghi sổ, không duyệt phiếu khi chỉ xem.");
guide("finance.treasury.bank-lines.list", treasury, ["Đối chiếu sao kê"], "Chọn Đối soát, xem Đối chiếu sao kê. Đối chiếu mã ngân hàng, ngày, số tiền và trạng thái khớp; không chọn Ghép phiếu nếu chỉ tra cứu.");
guide("finance.treasury.periods.list", treasury, ["Xem lịch sử & số dư"], "Chọn Chốt sổ quỹ, xem tháng và trạng thái kỳ. Mở Xem lịch sử & số dư để đọc lần chốt/mở lại và số dư tại thời điểm đó; không bấm Chốt hoặc Mở lại khi chỉ xem.");
guide("api.get.65204362fe283948", finance + "pages/FinancialManagementPage.tsx", ["Từ ngày", "Đến ngày"], "Trong Tài chính, chọn Thu - Chi/Lãi lỗ/VAT theo phần cần xem, chọn kỳ hoặc Từ ngày/Đến ngày và đúng chi nhánh. Đọc số liệu và Nguồn dữ liệu và giới hạn báo cáo; có thể xuất bảng đang xem để đối chiếu, không gộp các kỳ khác nhau.");
guide("finance.management.debts.list", finance + "pages/DebtManagementPanel.tsx", ["Phải thu khách hàng", "Phải trả nhà cung cấp"], "Mở Công nợ, chọn Phải thu khách hàng hoặc Phải trả nhà cung cấp. Tìm tên/mã, lọc hạn, đọc giá trị gốc, đã trả, còn nợ và chứng từ. Với phiếu nhập chưa ghi nợ, xem lựa chọn trong Ghi nợ rồi đóng nếu chỉ tra cứu.");
guide("api.post.c7f205ec27eeab37", finance + "components/PayableNoteForm.tsx", ["Lưu phiếu ghi nợ"], "Trong Công nợ → Phải trả nhà cung cấp, chọn Ghi nợ. Chọn phiếu nhập đã xác nhận, đối chiếu nhà cung cấp/giá trị, nhập hạn trả và số đã thanh toán trước đó.", "Kiểm tra số nợ còn lại rồi Lưu phiếu ghi nợ; mở danh sách công nợ để kiểm tra chứng từ. Không tạo lại khoản phải trả đã có.");
guide("finance.voucher.create", finance + "pages/FinancialManagementPage.tsx", ["Tạo phiếu thu / chi"], "Trong Thu - Chi, chọn Tạo phiếu thu / chi. Chọn loại, ngày, danh mục, cách tính vào lãi lỗ, số tiền, phương thức và đối tượng; kiểm tra giao dịch chưa có từ nguồn khác rồi lưu.", "Đối chiếu phiếu và tổng thu/chi. Thu nợ hoặc trả nhà cung cấp cần đi qua chức năng Công nợ để tránh ghi trùng.");
guide("api.post.5213d6b07cbffd29", finance + "pages/FinancialManagementPage.tsx", ["Đảo phiếu", "Lý do đảo phiếu"], "Trong Thu - Chi, tìm đúng phiếu và chọn Đảo phiếu. Nhập ngày điều chỉnh, lý do rồi xác nhận; kiểm tra bút toán đảo và số tiền thu/chi sau xử lý. Không lập phiếu mới cùng chiều để thay đảo giao dịch.");
guide("api.post.00f98f7f46e21cf0", finance + "pages/DebtManagementPanel.tsx", ["Ghi nhận xử lý công nợ", "Ngày hẹn trả"], "Mở đúng khoản công nợ → Theo dõi. Chọn trạng thái xử lý, nhập ngày/số tiền hẹn trả, người phụ trách và ghi chú cần thiết rồi lưu. Mở lại để kiểm tra; ghi nhận hẹn trả không có nghĩa đã thu tiền.");
guide("finance.tax.create", finance + "pages/FinancialManagementPage.tsx", ["Ghi nhận hóa đơn VAT"], "Mở VAT → Ghi nhận hóa đơn VAT. Điền loại đầu vào/đầu ra, ngày, số hóa đơn, mã số thuế, đối tác, tiền trước thuế, thuế suất và điều kiện khấu trừ rồi lưu.", "Đối chiếu dòng VAT mới và tổng kỳ; đây là ghi nhận sổ VAT nội bộ, không phải phát hành hóa đơn điện tử.");
guide("finance.tax.from-invoice", finance + "pages/FinancialManagementPage.tsx", ["Xác nhận hóa đơn bán lẻ vào sổ VAT nội bộ", "Hóa đơn đã phát hành"], "Trong VAT, mở chức năng ghi nhận hóa đơn đã phát hành, chọn đúng hóa đơn bán lẻ và xác nhận vào sổ VAT nội bộ. Kiểm tra mã hóa đơn, ngày, tiền trước thuế/VAT và tránh ghi lại hóa đơn đã có trong sổ.");
guide("api.put.86ec1b1dded51aa0", finance + "pages/FinancialManagementPage.tsx", ["VAT chuyển kỳ / cấu hình", "Kỳ cấu hình"], "Mở VAT chuyển kỳ / cấu hình, chọn đúng kỳ. Sửa ngân sách chi phí cố định hoặc VAT chuyển kỳ trước theo yêu cầu, nhập ghi chú rồi lưu; mở lại kỳ và đối chiếu cấu hình/báo cáo.");
guide("finance.asset.schedule", finance + "pages/FixedAssetsPage.tsx", ["Lịch khấu hao"], "Trong Tài sản, tìm mã hoặc tên, mở đúng tài sản. Xem Lịch khấu hao theo kỳ và giá trị; không chạy khấu hao mới khi chỉ tra lịch.");
guide("api.post.a5ab5625c92c88b1", finance + "pages/FixedAssetsPage.tsx", ["Lý do thanh lý?"], "Mở đúng tài sản đang được phép thanh lý, chọn Thanh lý và nhập lý do. Luồng hiện ghi thời điểm hiện tại và số tiền thanh lý bằng 0; chỉ dùng khi đó là yêu cầu phù hợp.", "Nếu cần ngày khác hoặc số tiền thu hồi khác 0, dừng để người quản trị xử lý qua công cụ phù hợp. Khi thanh lý thành công, kiểm tra trạng thái Đã thanh lý và lịch sử biến động.");
guide("finance.asset.inventory.list finance.asset.inventory.detail finance.asset.inventory.variance", finance + "pages/AssetInventoryPage.tsx", ["Mở phiên kiểm kê", "variance.counts"], "Mở Kiểm kê tài sản, chọn phiên theo mã/tên/ngày. Mở chi tiết để đọc tài sản và kết quả Chưa kiểm/Khớp/Hư hỏng/Thiếu/Thừa, cùng tổng hợp chênh lệch. Không Ghi nhận hoặc Chốt phiên nếu chỉ tra cứu.");
guide("finance.receivable.aging", finance + "pages/AgingReportPage.tsx", ["Phân tích tuổi nợ"], "Mở Tuổi nợ → Xem báo cáo tuổi nợ theo nhóm cũ. Đọc tổng theo nhóm 0–30, 31–60, 61–90 và trên 90 ngày; chọn nhóm để xem khoản nợ nguồn và đối chiếu ngày hạn.");
guide("finance.reminders.runs.list finance.reminders.runs.detail", finance + "pages/FinanceRemindersPage.tsx", ["Nhắc nợ quá hạn", "selected.deliveries"], "Mở Nhắc nợ → Xem lịch gửi nhắc nợ. Chọn ngày/lượt chạy để xem người nhận/kênh, trạng thái, số lần thử và lỗi từng lần gửi. Không bấm Chạy nhắc nợ hoặc Retry khi chỉ tra lịch sử.");
guide("api.delete.9043f4e5cc3aefab", "src/modules/student-management/pages/Partners/PartnersPage.tsx", ["deletingPartner"], "Mở danh sách đối tác, tìm đúng người và chọn Xóa. Đọc tên đối tác và cảnh báo liên kết trước khi xác nhận; kiểm tra danh sách sau xử lý. Nếu máy chủ từ chối do dữ liệu liên quan, giữ nguyên lý do, không xóa học viên hoặc hoa hồng để vượt điều kiện.");
const student = "src/modules/student-management/";
guide("student.learning-history", student + "components/Student/DetailTabs/QualityTab.tsx", ["Lộ trình học tập"], "Mở hồ sơ học viên và phần tiến trình/chất lượng học tập. Xem Lớp đã tham gia, Khóa học đã hoàn thành và Lộ trình học tập; đối chiếu thời gian vào/rời lớp và kết quả thi.");
guide("api.patch.5bb1b2bfdbad4548", student + "pages/Notifications/NotificationsPage.tsx", ["handleMarkInstallmentPaid"], "Chỉ khi bảng kết quả gửi nhắc học phí đang mở và có đúng học viên/đợt cần đánh dấu, dùng thao tác đánh dấu đã thu trên dòng đó. Kiểm tra trạng thái mới; thao tác đánh dấu không thay thế phiếu thu.", "Nếu không còn bảng kết quả phù hợp, không gửi thêm thông báo để mở lại nút này. Cần xử lý đợt học phí qua chức năng được hỗ trợ hoặc người quản trị.");
guide("student.exam.result.update", student + "pages/Exams/ExamsPage.tsx", ["onSaveStudentScores", "/students/${studentId}/result"], "Mở đúng đợt thi và danh sách thí sinh. Chọn thí sinh, cập nhật kết quả Đậu/Trượt hoặc kết quả tương ứng theo control trên dòng; kiểm tra trạng thái lưu và hồ sơ thí sinh sau khi tải lại.");
guide("student.exam.grade-results.update", student + "pages/Exams/ExamsPage.tsx", ["onSaveStudentScores"], "Mở đúng đợt thi và phần nhập điểm. Điền điểm của các thí sinh cần cập nhật, kiểm tra thang điểm và không ghi đè học viên ngoài yêu cầu; lưu điểm. Đối chiếu số học viên được báo đã lưu và từng dòng điểm.");
guide("student.notification.delete", student + "pages/Notifications/NotificationsPage.tsx", ["handleDeleteNotification"], "Trong Thông báo, tìm bản ghi lịch sử cần xóa và dùng thao tác xóa của bản ghi. Kiểm tra nội dung và xác nhận nếu có; tải lại lịch sử để đối chiếu. Xóa lịch sử không thu hồi email/tin nhắn đã gửi.");
guide("student.resource.create", student + "pages/Resources/components/AddResourceModal.tsx", ["/student-resources"], "Mở Thiết bị hoặc Phòng học đúng loại tài nguyên, chọn thêm mới. Nhập tên, loại/phân loại, số lượng hoặc sức chứa và trường bắt buộc của biểu mẫu; kiểm tra chi nhánh rồi lưu. Tìm lại tài nguyên trong danh sách trước khi tạo thêm.");
guide("student.batch.learner.add", student + "components/Batches/ManageLearnersModal.tsx", ["/learners"], "Mở đúng lớp → quản lý học viên. Tìm và chọn học viên chưa có trong lớp, kiểm tra học phí/điều kiện lớp được hiển thị rồi xác nhận thêm; kiểm tra danh sách lớp sau khi lưu. Không tạo hồ sơ học viên mới nếu người đó đã có hồ sơ.");
guide("student.batch.learner.remove", student + "components/Batches/ManageLearnersModal.tsx", ["method: 'DELETE'"], "Trong quản lý học viên của lớp, tìm đúng người và chọn gỡ khỏi lớp. Đọc cảnh báo về liên kết và lịch sử trước khi xác nhận; kiểm tra danh sách lớp. Đây không phải xóa hồ sơ học viên hoặc bảo lưu.");
guide("student.schedule.list", student + "components/Dashboard/ScheduleCalendar.tsx", ["useSchedule"], "Mở Tổng quan học viên và lịch tổng hợp, chọn ngày/tháng cùng trung tâm cần xem. Đối chiếu sự kiện lớp, kỳ thi hoặc lịch tài nguyên trong đúng khoảng; mở mục lịch để xem thông tin nguồn.");
guide("student.assignment.list student.assignment.submissions.list", student + "components/Batches/AssignmentModal.tsx", ["Bài tập & Minh chứng", "Chi tiết & Chấm điểm"], "Mở lớp → Giao bài tập để xem Bài tập & Minh chứng. Chọn bài cần tra, xem danh sách Đã nộp/Chưa nộp/Nộp muộn, mở Chi tiết & Chấm điểm để đọc minh chứng; không nhập điểm hoặc nộp hộ khi chỉ tra cứu.");
guide("student.quality.list", student + "pages/StudentQuality/StudentQualityPage.tsx", ["Mọi mức đánh giá"], "Mở Chất lượng học viên, lọc lớp, khóa, mức đánh giá và tìm tên/số điện thoại. Đọc chuyên cần, bài tập, thái độ và điểm thi; mở học viên để xem nguồn chi tiết, phân biệt chưa có dữ liệu với điểm bằng không.");
guide("student.quality.mini-tests.list", student + "pages/StudentQuality/StudentQualityPage.tsx", ["Toàn bộ mini test"], "Trong Chất lượng học viên, chọn đúng học viên và lớp, mở tiến trình đào tạo. Xem Toàn bộ mini test/Điểm thi, đọc tên bài, điểm và thang điểm; không chấm hoặc xóa điểm khi chỉ xem.");
guide("student.quality.assignment.grade", student + "pages/StudentQuality/StudentQualityPage.tsx", ["Bài tập và điểm số", "Chấm bài"], "Mở đúng học viên-lớp trong Chất lượng học viên → cập nhật đánh giá → Bài tập và điểm số. Chọn bài cần chấm, nhập điểm đúng thang và Phản hồi rồi Lưu; mở lại bài tập để đối chiếu điểm.");
const roadmap = student + "pages/LearningRoadmap/LearningRoadmapPage.tsx";
guide("student.learning-roadmap.list student.learning-roadmap.steps.list", roadmap, ["Xem preview lộ trình"], "Mở Lộ trình & chờ lớp → Lộ trình, chọn Xem preview lộ trình ở đúng mục. Đọc thứ tự khóa học/chặng, sĩ số và điều kiện chuyên cần/bài tập/thi; không chỉnh sửa hoặc xóa chặng khi chỉ xem.");
guide("student.learning-roadmap.progression.list", roadmap, ["Đánh giá lên lớp", "Đối chiếu"], "Chọn Đánh giá lên lớp, chọn lớp nguồn và lộ trình rồi Đối chiếu. Đọc điều kiện từng học viên và quyết định Học tiếp/Chờ xác nhận/Không tiếp tục; chưa lưu quyết định nếu chỉ muốn xem.");
guide("student.learning-roadmap.promote", student + "components/Batches/DirectLevelPromotionModal.tsx", ["promoteBatchStudents"], "Mở chức năng chuyển cấp/lên lớp từ đúng lớp nguồn. Chọn lộ trình và lớp đích phù hợp, đối chiếu điều kiện, đánh dấu đúng học viên rồi xác nhận chuyển.", "Mở lớp đích và lịch sử lớp của học viên để kiểm tra; nếu điều kiện chưa đạt hoặc thiếu lớp đích, xử lý dữ liệu trước, không tạo lớp thay khi chưa được yêu cầu.");
guide("student.learning-roadmap.waitlist.list", roadmap, ["Danh sách chờ", "Lọc theo lộ trình"], "Mở Danh sách chờ, lọc lộ trình. Xem học viên, mốc đích, lớp nguồn, sở thích và số ngày chờ; chuyển trang để xem đầy đủ kết quả.");
guide("student.learning-roadmap.waitlist.place", roadmap, ["Chọn lớp đích sắp khai giảng", "Chỉ được xếp học viên cùng mốc đích trong một lần."], "Trong Danh sách chờ, chọn các học viên cùng mốc đích và lớp đích sắp khai giảng. Đối chiếu sĩ số, khóa học và danh sách đã chọn rồi bấm Xếp.", "Kiểm tra học viên xuất hiện trong lớp đích và không còn chờ tại mốc vừa xử lý; không xếp lặp nếu chỉ chưa tải lại được danh sách.");
guide("partner.commission.levels.list", student + "pages/Partners/components/CommissionLevelModal.tsx", ["Cấu hình Level Hoa hồng"], "Mở Đối tác → cấu hình Level Hoa hồng, chọn trung tâm quản lý. Đọc tên cấp, doanh số tối thiểu và tỷ lệ hoa hồng; không lưu hoặc xóa khi chỉ xem.");
guide("api.delete.abafb6f27753de55", student + "pages/Partners/components/CommissionLevelModal.tsx", ["/partners/commission-levels/${id}"], "Trong cấu hình Level Hoa hồng, tìm đúng cấp và dùng nút xóa. Kiểm tra trung tâm và tên cấp trong xác nhận nếu có; nếu hệ thống từ chối do dữ liệu liên quan, giữ lý do. Tải lại danh sách để xác nhận kết quả.");
guide("partner.bulk.create", student + "pages/Partners/components/ImportPartnerModal.tsx", ["Nhập danh sách đối tác", "Kiểm tra lỗi trước khi nhập"], "Mở nhập danh sách đối tác, tải file mẫu và điền tên, số điện thoại cùng thông tin cần nhập. Chọn tệp Excel/CSV, kiểm tra lỗi trước khi nhập và sửa các dòng trùng/không hợp lệ.", "Xác nhận nhập những dòng hợp lệ, đọc Kết quả nhập dữ liệu với số mới tạo và số bỏ qua/lỗi. Kiểm tra danh sách trước khi nhập lại file để tránh trùng đối tác.");
const worker = "src/modules/worker-management/";
guide("worker.project.worker.remove", worker + "pages/WorkerProjectsPage.tsx", ["Quản lý lao động", "khỏi dự án"], "Mở đúng dự án → Quản lý lao động. Tìm người cần gỡ, chọn nút Gỡ người đó khỏi dự án và xác nhận nếu có; kiểm tra danh sách thành viên sau xử lý. Thao tác không xóa hồ sơ lao động.");
guide("api.get.975d2e3032a3229a", worker + "pages/WorkerContractsPage.tsx", ["Chỉ xem hợp đồng cảnh báo", "expiringSummary"], "Mở Hợp đồng lao động, xem tổng hợp cảnh báo sắp hết hạn, chọn Chỉ xem hợp đồng cảnh báo. Đối chiếu ngày hết hạn và người lao động trong danh sách; không gia hạn nếu chỉ yêu cầu báo cáo.");
guide("worker.labor.contract.history", worker + "pages/WorkerContractsPage.tsx", ["Lịch sử các kỳ hợp đồng"], "Tìm hợp đồng theo mã/tên, chọn Lịch sử hợp đồng. Xem các kỳ, thời hạn và trạng thái khóa; không dùng Gia hạn khi chỉ xem lịch sử.");
guide("worker.attendance.list", worker + "pages/WorkerProjectsPage.tsx", ["Lịch sử & Thống kê điểm danh"], "Mở đúng dự án → Lịch sử & Thống kê điểm danh. Chọn Từ ngày/Đến ngày, mở ngày cần xem để đọc giờ vào/ra, tổng giờ và trạng thái từng lao động; có thể Xuất Excel để đối chiếu.");
guide("worker.attendance.mark", worker + "components/WorkerTimekeepingPanel.tsx", ["Check-in", "Ghi nhận tiếp"], "Mở dự án → Điểm danh thủ công & QR → Chấm công lao động. Kiểm tra đúng người và trạng thái hiện tại, chọn Check-in hoặc Ghi nhận tiếp theo lần chấm cần ghi.", "Làm mới và kiểm tra lịch sử ngay sau lần chấm. Không bấm nhiều lần khi chưa rõ kết quả vì có thể ghi thêm lần chấm hoặc đổi vào/ra.");
guide("worker.notification.create", worker + "pages/WorkerNotificationsPage.tsx", ["Gửi thông báo", "Lịch sử thông báo"], "Mở Thông báo lao động, nhập Tiêu đề và Nội dung, kiểm tra chi nhánh/phạm vi người nhận rồi Gửi thông báo. Xem bản ghi mới trong Lịch sử thông báo; tránh gửi lại khi chỉ chưa tải được danh sách.");
guide("worker.partner.worker-referral.list", worker + "pages/WorkersPage.tsx", ["listReferralsForWorker"], "Trong Lao động, mở chỉnh sửa đúng hồ sơ để xem đối tác giới thiệu hiện tại. Đối chiếu đối tác và trạng thái nguồn giới thiệu, rồi đóng không lưu nếu chỉ tra cứu. Màn hình này tập trung nguồn hiện hành; lịch sử đầy đủ cần xem tại hồ sơ đối tác.");
guide("healthcare.visit.create", "src/modules/healthcare/RecordEditor.tsx", ["Mã lượt khám", "Ngày khám", "Lưu"], "Trong Lượt khám, chọn Ghi lượt khám. Tìm đúng bệnh nhân theo tên/số điện thoại, nhập ngày khám, bác sĩ, phòng, dịch vụ và các thông tin cần thiết.", "Kiểm tra bệnh nhân và dữ liệu rồi Lưu; tìm lại lượt khám theo bệnh nhân/ngày. Ghi nhận thanh toán tham khảo không thay thế một phiếu thu tài chính.");
guide("healthcare.catalog.list", "src/modules/healthcare/HealthcarePage.tsx", ["Loại danh mục", "Tìm mã hoặc tên danh mục"], "Mở Danh mục y tế, lọc loại bác sĩ/phòng/dịch vụ và trạng thái, tìm theo mã/tên. Xem dữ liệu được phép sử dụng tại chi nhánh; không thêm hoặc ngừng sử dụng khi chỉ tra cứu.");
guide("healthcare.staff.list", "src/modules/healthcare/RecordEditor.tsx", ["Chọn nhân viên phụ trách"], "Mở biểu mẫu việc chăm sóc và danh sách Chọn nhân viên phụ trách để xem nhân viên được phân công tại chi nhánh. Đóng không lưu nếu chỉ tra cứu; không tạo việc chăm sóc để lấy danh sách.");
guide("inventory.supplier.list", "src/components/inventory/ReceivingSection.tsx", ["listSupplierPartners"], "Mở Nhập hàng và biểu mẫu phiếu nhập, xem danh sách Nhà cung cấp có thể chọn. Đối chiếu tên/mã và trạng thái; đóng biểu mẫu nếu chỉ tra cứu, không tạo phiếu nhập.");
guide("inventory.stock-log.list", "src/components/inventory/StockLogPanel.tsx", ["StockLogPanel"], "Mở Giao dịch kho, chọn chi nhánh/kho và bộ lọc loại phiếu, thời gian cần xem. Đối chiếu phiếu nhập/xuất, trạng thái và số lượng; mở chi tiết phiếu khi cần, không thay trạng thái khi chỉ tra cứu.");
const inventory = "src/components/inventory/";
guide("inventory.catalog.workspace.get", inventory + "ProductCatalogV2Section.tsx", ["Thiết lập danh mục", "Chế độ hiển thị của doanh nghiệp"], "Mở Hàng hóa/Dịch vụ → Thiết lập danh mục, xem Chế độ hiển thị của doanh nghiệp và các nhóm cấu hình. Không đổi chế độ hoặc chọn Lưu chế độ khi chỉ xem.");
guide("inventory.prices.list", inventory + "catalog/ProductViewerModal.tsx", ["listPrices"], "Tìm sản phẩm trong danh mục, mở Xem chi tiết và xem giá từng SKU tại chi nhánh đã chọn. Giá vốn chỉ xuất hiện theo quyền; không coi Chưa có giá là giá bằng không.");
guide("api.put.f369bafc104121fe", inventory + "catalog/VariantModal.tsx", ["Giá bán (₫) *", "Giá vốn (₫)", "Lưu thay đổi"], "Mở Sửa sản phẩm → đúng SKU → Sửa SKU. Sửa Giá bán và Giá vốn nếu có quyền, giữ nguyên các thuộc tính khác; chọn Lưu thay đổi. Mở lại giá của SKU trong đúng chi nhánh để đối chiếu.");
guide("inventory.catalog.resource.list", inventory + "catalog/CatalogSetupModal.tsx", ["Quản lý dữ liệu dùng chung"], "Trong Thiết lập danh mục, chọn Nhóm danh mục, Thương hiệu hoặc Thuộc tính cần xem. Đọc cây nhóm hoặc danh sách tương ứng; với đơn vị tính, xem danh sách Đơn vị tính cơ bản trong biểu mẫu sản phẩm rồi đóng mà không lưu.");
guide("api.post.c29d50d7a2ebd989", inventory + "catalog/CatalogSetupModal.tsx", ["Thêm Cấp 1", "Tạo mới"], "Chọn đúng loại dữ liệu trong Thiết lập danh mục. Với nhóm, chọn cấp và thư mục cha; với thương hiệu/thuộc tính, chọn tạo mục mới rồi nhập tên, mã, trạng thái và cấu hình của loại đó.", "Kiểm tra dữ liệu rồi Tạo mới/Lưu theo biểu mẫu, đối chiếu mục mới trong danh sách. Đơn vị tính được tạo từ biểu mẫu sản phẩm bằng Tạo đơn vị tính.");
guide("api.patch.ad1b26d154f5621c", inventory + "catalog/CatalogSetupModal.tsx", ["Lưu thay đổi", "Sửa ngành hàng"], "Mở đúng loại danh mục, tìm mục và chọn Sửa. Sửa tên, trạng thái, thư mục cha hoặc thuộc tính được yêu cầu; Lưu thay đổi rồi mở lại kiểm tra. Với loại không có nút Sửa trên màn hình, dừng và yêu cầu người quản trị xử lý, không tạo mục mới thay thế.");
guide("api.delete.9301905784a3a33e", inventory + "catalog/CatalogSetupModal.tsx", ["Xóa thuộc tính", "Xóa ngành hàng"], "Chọn đúng loại danh mục và mục cần xóa, dùng nút Xóa rồi đọc xác nhận. Nếu bị từ chối vì đang được sử dụng, giữ nguyên lý do; không xóa sản phẩm liên quan để vượt điều kiện. Tải lại danh sách sau khi xóa thành công.");
guide("inventory.catalog.unit.create", inventory + "catalog/ProductEditorModal.tsx", ["Tạo đơn vị tính mới", "Tạo và chọn"], "Mở biểu mẫu sản phẩm, tại Đơn vị tính cơ bản chọn Tạo đơn vị tính mới. Nhập tên, ký hiệu, nhóm đo lường và số chữ số thập phân từ 0 đến 6; chọn Tạo và chọn.", "Kiểm tra đơn vị mới trong lựa chọn. Nếu chỉ tạo đơn vị tính, đóng biểu mẫu sản phẩm mà không tạo thêm sản phẩm.");
guide("inventory.variant.bulk.update", inventory + "catalog/BulkVariantModal.tsx", ["Các SKU đã chọn:", "Lưu thay đổi"], "Trong sản phẩm, chọn đúng các SKU và mở Sửa hàng loạt. Chọn trạng thái hoặc cách theo dõi kho cần đổi, để Giữ nguyên cho phần không đổi; kiểm tra danh sách rồi Lưu thay đổi. Đối chiếu từng SKU sau khi tải lại.");
guide("inventory.variant.bulk.delete", inventory + "catalog/ProductEditorModal.tsx", ["Xóa SKU đã chọn?"], "Mở Sửa sản phẩm, chọn đúng các SKU và thao tác Xóa SKU. Đọc xác nhận Xóa SKU đã chọn rồi đồng ý khi đúng danh sách; chỉ SKU chưa phát sinh giao dịch mới được xóa. Tải lại sản phẩm để kiểm tra kết quả.");
guide("inventory.warehouse.locations.list", inventory + "WarehouseSection.tsx", ["Chọn kho lưu trữ"], "Mở Kho hàng, mở lựa chọn Chọn kho lưu trữ để xem các kho được phép truy cập. Chọn kho cần tra và đối chiếu thông tin kho trên bảng tồn; không tạo kho khi chỉ xem danh sách.");
guide("api.post.f03e901c8ee14a8f", inventory + "InventoryCountingSection.tsx", ["Bắt đầu đếm hàng"], "Trong Kho hàng, chọn kho và Kiểm kê kho, mở đúng phiên chưa bắt đầu. Kiểm tra kho và phạm vi SKU rồi chọn Bắt đầu đếm hàng; xác nhận phiên chuyển sang Đang kiểm đếm. Chưa chốt hoặc điều chỉnh tồn ở bước này.");
const hr = "src/components/hr/";
guide("branch.pending.delete", "src/components/settings/BranchManagementTab.tsx", ["Đã hủy tạo chi nhánh"], "Nếu đang ở bước tạo Chủ chi nhánh sau khi vừa tạo chi nhánh mới, dùng Hủy/đóng quy trình tạo theo hộp thoại để hủy chi nhánh chưa hoàn tất. Kiểm tra danh sách không còn chi nhánh chờ; không dùng Vô hiệu hóa thay cho hủy chi nhánh đã tạo dở.");
guide("timekeeping.today.me", "src/pages/Header.tsx", ["Đã hoàn thành chấm công hôm nay"], "Đăng nhập tài khoản của mình, xem trạng thái chấm công trên thanh đầu trang: chưa vào, đang trong ca hoặc đã hoàn thành. Chỉ xem trạng thái; không bấm Check-In/Check-Out nếu yêu cầu chỉ tra cứu.");
guide("timekeeping.company.location", "src/components/settings/ErpConfigTab.tsx", ["Cấu hình Vị trí Chấm công (GPS)"], "Trong Cài đặt → Cấu hình → Cấu hình chung, xem Cấu hình Vị trí Chấm công: tọa độ, bán kính, giờ vào/ra, nghỉ trưa và ngày làm việc. Không chọn Lưu Cấu hình khi chỉ tra cứu.");
guide("api.patch.cbf8c2b9d544f837", "src/components/settings/ErpConfigTab.tsx", ["Lưu Cấu hình"], "Mở Cấu hình Vị trí Chấm công bằng tài khoản được quản lý cấu hình. Sửa đúng tọa độ, bán kính, giờ vào/ra, nghỉ trưa và ngày làm việc cần thay đổi; dùng Lấy vị trí hiện tại của tôi chỉ khi đang ở đúng địa điểm.", "Kiểm tra phạm vi áp dụng rồi chọn Lưu Cấu hình; mở lại để đối chiếu. Cấu hình chi nhánh riêng có thể được quản lý tại Chi nhánh, không tự thay thế bằng vị trí công ty.");
guide("api.get.efd26957a4dbe889", "src/components/settings/WorkShiftsTab.tsx", ["Phân ca nhân viên"], "Mở Nhân sự → Lịch → Ca làm việc, xem Phân ca nhân viên. Đối chiếu nhân viên, ca đang gán và ngày bắt đầu; không chọn Gán nếu chỉ xem.");
guide("api.post.5511b45cf3a736d1", "src/components/settings/WorkShiftsTab.tsx", ["Ngày bắt đầu phân ca", "Chọn nhanh nhân viên"], "Trong Lịch → Ca làm việc → Phân ca nhân viên, chọn đúng nhân viên, ca làm việc và ngày bắt đầu. Kiểm tra số người đã chọn rồi dùng nút Gán cho các nhân viên đã chọn; tải lại để kiểm tra ca của từng người.");
guide("api.get.5d0d3ea4fc0d9efb", "src/components/settings/EmployeeWorkHoursTab.tsx", ["Giờ làm việc riêng của nhân viên"], "Mở Nhân sự → Lịch → Giờ làm việc riêng, tìm theo tên/email. Xem nhân viên dùng Giờ riêng hay Theo công ty; mở Chỉnh sửa để xem ngày/giờ chi tiết rồi Hủy khi không cần thay đổi.");
guide("timekeeping.work-calendar.sync", "src/components/settings/CompanyWorkCalendarTab.tsx", ["Đã đồng bộ lịch nghỉ lễ.", "Năm lịch"], "Mở Lịch → Lịch nghỉ lễ, chọn Năm lịch rồi Đồng bộ. Chờ thông báo hoàn tất, kiểm tra ngày, loại và cờ Áp dụng trong danh sách; không coi mọi ngày đồng bộ là được áp dụng nếu cờ đang tắt.");
guide("hr.contract.settings.get", hr + "ContractsTab.tsx", ["Cài đặt thời gian cảnh báo hợp đồng sắp hết hạn"], "Mở Hợp đồng, chọn cài đặt thời gian cảnh báo cạnh Báo trước. Xem số ngày hiện tại rồi đóng hộp thoại nếu chỉ tra cứu.");
guide("hr.contract.settings.update", hr + "ContractsTab.tsx", ["Hoặc nhập số ngày tùy chỉnh (1 – 365 ngày):"], "Mở cài đặt cảnh báo hợp đồng sắp hết hạn. Chọn mốc có sẵn hoặc nhập số ngày từ 1 đến 365, kiểm tra phạm vi toàn công ty rồi Lưu. Đối chiếu giá trị Báo trước và các hợp đồng cảnh báo.");
guide("api.get.b44c64519e939e0a", hr + "ContractsTab.tsx", ["Gia hạn hợp đồng", "Chưa có lịch sử gia hạn hợp đồng."], "Trong Hợp đồng, chọn Gia hạn hợp đồng, tìm nhân viên/email/phòng ban. Xem ngày gia hạn, hạn cũ, hạn mới, lý do và tài liệu; không chọn Tạo gia hạn khi chỉ xem lịch sử.");
guide("recruitment.pipeline.get", hr + "recruitment/RecruitmentApplicantsView.tsx", ["pipeline?.stages"], "Mở Tuyển dụng → Ứng viên, chuyển sang bảng Kanban để xem các cột giai đoạn đang hoạt động. Đọc tên bước và số ứng viên; không chuyển giai đoạn nếu chỉ xem quy trình.");
guide("recruitment.applicant.transition", hr + "recruitment/RecruitmentApplicantsView.tsx", ["transitionApplicant"], "Mở Tuyển dụng → Ứng viên, chọn đúng ứng viên và thay đổi giai đoạn bằng lựa chọn chuyển bước trong hồ sơ. Kiểm tra bước hiện tại và bước đích trước khi xác nhận.", "Xem vị trí ứng viên trên bảng và Lịch sử quy trình để xác nhận bước mới; nếu máy chủ từ chối chuyển, giữ nguyên lý do và xử lý điều kiện còn thiếu.");
guide("recruitment.applicant.history", hr + "recruitment/ApplicantDetailPanel.tsx", ["Lịch sử quy trình"], "Mở đúng hồ sơ ứng viên → Lịch sử quy trình. Đọc từng lần chuyển bước và thông tin liên quan; kiểm tra đúng ứng viên/tin tuyển dụng trước khi kết luận.");
guide("api.get.15793bc7bd272c4c task.kpi.monthly", hr + "KanbanMonthlyKpiView.tsx", ["Chọn tháng KPI", "KPI công việc theo tháng"], "Mở Giao Việc → KPI công việc theo tháng, chọn tháng/năm. Đọc từng nhân viên, tổng công việc, đạt và chưa đạt KPI; kiểm tra phạm vi nhân viên/chi nhánh trước khi sử dụng số liệu.");
guide("task.activity.update", hr + "KanbanTaskProgress.tsx", ["Lưu báo cáo tiến độ", "Gửi yêu cầu trợ giúp"], "Mở đúng công việc → Tiến độ & trợ giúp. Nếu báo cáo, chọn Báo cáo tiến độ, nhập tiến độ và nội dung rồi Lưu báo cáo tiến độ; nếu cần hỗ trợ, chọn Yêu cầu trợ giúp, người hỗ trợ và lý do rồi gửi.", "Kiểm tra hoạt động vừa lưu trong công việc. Chỉ dùng Đã giải quyết trợ giúp hoặc Tham gia hỗ trợ khi đúng hành động yêu cầu.");
guide("hr.leave.applications.list", hr + "LeaveRequestsTab.tsx", ["Tìm đơn...", "Loại đơn:"], "Mở Lịch → Chấm công & Lịch làm việc → Đơn từ. Tìm nhân viên/lý do, lọc loại đơn và yêu cầu, đọc thời gian, trạng thái và phản hồi. Không duyệt/từ chối khi chỉ tra cứu.");
guide("leave.balance.me", hr + "LeaveRequestsTab.tsx", ["Hạn mức", "Còn lại"], "Trong Đơn từ, mở Nộp đơn để xem số phép Hạn mức, Đã dùng, Chờ duyệt và Còn lại của mình. Đóng biểu mẫu sau khi xem; không nộp đơn chỉ để kiểm tra số dư.");
guide("hr.calendar.events.list", hr + "CalendarTab.tsx", ["Danh mục lịch", "Sự kiện"], "Mở Lịch → Chấm công & Lịch làm việc → Lịch trình, chọn ngày/tháng và lọc Sự kiện. Mở sự kiện để xem thời gian, người tham gia, địa điểm và nội dung.");
guide("hr.calendar.event.create", hr + "CreateMeetingModal.tsx", ["Tạo lịch họp / hẹn", "Sự kiện chung"], "Trong Lịch trình, mở tạo lịch họp/lịch hẹn. Nhập tiêu đề, chọn phân loại Sự kiện chung nếu phù hợp, ngày/giờ hoặc Cả ngày, địa điểm/link và người tham gia.", "Kiểm tra lịch và nội dung rồi chọn Tạo lịch họp / hẹn; mở đúng ngày trên lịch để đối chiếu sự kiện mới.");
guide("hr.calendar.event.update", hr + "CreateMeetingModal.tsx", ["Cập nhật lịch"], "Mở đúng sự kiện trong Lịch trình và chọn chỉnh sửa. Đổi các thông tin được yêu cầu, kiểm tra ngày/giờ/người tham gia rồi Cập nhật lịch; mở lại sự kiện để đối chiếu.");
guide("hr.training.incomplete.list hr.training.progress", hr + "TrainingTab.tsx", ["Giám sát tiến độ học nhân viên"], "Mở Đào tạo → Giám sát tiến độ học nhân viên bằng tài khoản có quyền. Xem từng nhân viên/khóa học và tiến độ hoàn thành; khi cần người chưa hoàn thành, chỉ lấy các mục chưa đạt hoàn tất trong danh sách, không dùng thao tác hoàn thành thay cho báo cáo.");
const payroll = "src/components/hr/payroll/";
const payrollPage = "src/components/hr/PayrollTab.tsx";
guide("payroll.reconciliation.schedule.get", payroll + "PayrollPublicationSchedule.tsx", ["Lịch tự động phát hành lương tạm tính"], "Trong PAYROLL → Phiếu lương & phát hành, xem Lịch tự động phát hành lương tạm tính: trạng thái tự động, ngày, giờ và kỳ được phát hành. Không lưu lịch khi chỉ tra cứu.");
guide("payroll.run.reconciliation.list payroll.run.complaints.list", payroll + "PayrollComplaintsPanel.tsx", ["Tìm khiếu nại", "Xem / xử lý"], "Trong PAYROLL, chọn đúng tháng rồi mở Phiếu lương & phát hành → Khiếu nại & Đối soát của nhân viên. Tìm theo tên/mã, lọc trạng thái và chọn Xem chi tiết hoặc Xem / xử lý; đọc số liệu và lịch sử trao đổi.");
guide("payroll.run.reconciliation.publish", payroll + "PayrollComplaintsPanel.tsx", ["Phát hành bảng lương tạm tính", "Cập nhật bản gửi nhân viên"], "Chọn đúng kỳ đang ở bước Nháp, lưu hết thay đổi trên bảng lương và kiểm tra số liệu. Trong Khiếu nại & Đối soát, chọn Phát hành bảng lương tạm tính hoặc Cập nhật bản gửi nhân viên.", "Kiểm tra trạng thái phát hành và danh sách nhân viên nhận bản đối soát. Đây là bảng tạm tính, không thay thế chốt kỳ hoặc thanh toán lương.");
guide("payroll.run.reconciliation.action", payroll + "PayrollReconciliationConversation.tsx", ["Gửi phản hồi", "Giải quyết khiếu nại"], "Mở đúng khiếu nại trong kỳ đang được phép xử lý, đọc khoản lương và trao đổi trước đó. Chọn Trả lời hoặc Giải quyết khiếu nại, nhập nội dung giải thích/kết quả và gửi phản hồi.", "Đối chiếu nội dung mới và trạng thái; nếu cần sửa số tiền, sửa trên bảng lương và phát hành lại theo quy trình, không coi phản hồi là đã thay đổi tiền lương.");
guide("payroll.employee.me.reconciliation", payroll + "EmployeePayrollReconciliation.tsx", ["Bảng lương tạm tính — Đối soát & Khiếu nại"], "Đăng nhập tài khoản nhân viên, mở Nhân sự → PAYROLL → Bảng lương tạm tính — Đối soát & Khiếu nại. Chọn kỳ được phát hành và kiểm tra từng khoản; nếu chưa có bản, chờ người quản lý phát hành.");
guide("payroll.employee.reconciliation.action", payroll + "PayrollReconciliationConversation.tsx", ["Gửi khiếu nại", "Xác nhận bảng lương"], "Trong bản đối soát của mình, chọn khoản cần hỏi và Gửi khiếu nại hoặc Trả lời, nhập nội dung rồi gửi. Nếu số liệu đã đúng, chọn Xác nhận bảng lương hoặc xác nhận kết quả giải quyết tương ứng.", "Đọc lại trao đổi và trạng thái xác nhận; không xác nhận số liệu còn sai. Không dùng tài khoản quản lý để phản hồi thay nhân viên.");
guide("payroll.period.variables.list", payroll + "PayrollCustomVariableManager.tsx", ["Khoản bổ sung"], "Trong PAYROLL → Chính sách & cách tính, xem Khoản bổ sung và trạng thái từng khoản. Không dùng Thêm khoản hoặc Bật/Tắt nếu chỉ cần xem.");
guide("payroll.period.variables.create", payroll + "PayrollCustomVariableManager.tsx", ["Thêm khoản", "Mã khoản", "Đơn vị khoản"], "Trong Khoản bổ sung, chọn Thêm khoản. Nhập mã, tên, đơn vị và giá trị mặc định nếu cần; kiểm tra mã không trùng rồi chọn Lưu. Xem khoản mới trong danh sách.");
guide("payroll.period.variables.activate", payroll + "PayrollCustomVariableManager.tsx", ["activatePeriodInputVariable"], "Tìm đúng khoản đang tắt trong Khoản bổ sung, chọn Bật. Tải lại danh sách để xác nhận khoản đã hoạt động; thao tác này không tự nhập giá trị cho từng nhân viên.");
guide("payroll.period.variables.retire", payroll + "PayrollCustomVariableManager.tsx", ["retirePeriodInputVariable"], "Tìm đúng khoản đang dùng trong Khoản bổ sung, chọn Tắt. Kiểm tra trạng thái mới; không xóa dữ liệu lương lịch sử để ngừng sử dụng khoản.");
guide("payroll.period.line-overrides.list", payrollPage, ["getLineOverrides", "Các khoản có thể chỉnh sửa"], "Chọn đúng kỳ PAYROLL, tìm nhân viên trong bảng lương. Xem Các khoản có thể chỉnh sửa và giá trị đã lưu; mở Chi tiết để đối chiếu cách tính, không sửa ô khi chỉ xem.");
guide("payroll.period.line-overrides.bulk", payrollPage, ["Lưu thay đổi dữ liệu lương", "Lý do đối soát"], "Chọn kỳ còn cho phép chỉnh, tìm từng nhân viên và sửa đúng ô trong Các khoản có thể chỉnh sửa. Kiểm tra các dòng thay đổi rồi chọn Lưu thay đổi.", "Nhập Lý do đối soát trong hộp xác nhận và lưu. Tải lại bảng, đối chiếu giá trị và thực nhận từng nhân viên; kiểm tra lỗi từng dòng trước khi kết luận toàn bộ đã lưu.");
guide("payroll.policy.list", payroll + "PayrollPolicyManager.tsx", ["Cách tính lương"], "Mở PAYROLL → Chính sách & cách tính → Cách tính lương. Xem các công thức/chính sách, thời gian áp dụng và trạng thái; không bấm Áp dụng nếu chỉ tra cứu.");
guide("payroll.policy.activate", payroll + "PayrollPolicyManager.tsx", ["Áp dụng", "Xác nhận thay thế"], "Trong Cách tính lương, chọn đúng chính sách rồi Áp dụng. Nếu có chồng thời gian, đọc danh sách công thức bị thay thế; chỉ Xác nhận thay thế khi đó là chủ ý. Kiểm tra nhãn Đang áp dụng sau xử lý.");
guide("payroll.policy.retire", payroll + "PayrollPolicyManager.tsx", ["Ngưng áp dụng công thức?"], "Tìm đúng chính sách, chọn Ngưng áp dụng. Đọc ảnh hưởng đến kỳ lương mới rồi xác nhận; kiểm tra chính sách không còn đang áp dụng. Không xóa kỳ lương cũ.");
guide("payroll.policy.clone", payroll + "PayrollPolicyManager.tsx", ["Nhân bản"], "Chọn Nhân bản trên đúng công thức nguồn, kiểm tra mã và tên bản mới cùng định nghĩa được sao chép. Lưu bản nháp rồi xem lại; nhân bản chưa đồng nghĩa áp dụng chính sách mới.");
guide("payroll.policy.delete", payroll + "PayrollPolicyManager.tsx", ["Xóa công thức?"], "Chọn Xóa tại đúng chính sách, đọc xác nhận và kiểm tra bản chưa bị khóa/chưa dùng trong kỳ chốt. Xác nhận Xóa công thức khi hợp lệ; nếu máy chủ từ chối, giữ lý do và không xóa dữ liệu liên quan để vượt điều kiện.");
guide("payroll.run.calculate", payrollPage, ["payrollService.calculateRun"], "Mở đúng kỳ lương đã có bản tính và đang ở bước Chuẩn bị. Kiểm tra dữ liệu công và chính sách, chọn Cập nhật bảng lương; chờ xử lý và đối chiếu thực nhận từng nhân viên.", "Nếu kỳ chưa có bản tính, nút Tính lương chạy thêm các bước khởi tạo/đồng bộ; không dùng để thay thao tác chỉ tính một lượt đã khóa công. Nếu kỳ đã kiểm tra/chốt, xử lý mở lại kỳ theo quyền trước.");
guide("payroll.employee.me.payslips payroll.employee.me.payslip.review-requests", "src/components/hr/EmployeePayslips.tsx", ["Phiếu lương của tôi", "Yêu cầu của các phiếu lương trước"], "Đăng nhập tài khoản nhân viên, mở PAYROLL → Phiếu lương của tôi. Chọn Xem chi tiết ở đúng kỳ để xem thu nhập, khấu trừ và thực nhận; xem trạng thái yêu cầu kiểm tra lại dưới phiếu và mục yêu cầu các phiếu trước.");
guide("payroll.employee.me.payslip.review.request", "src/components/hr/EmployeePayslips.tsx", ["Nội dung cần kiểm tra", "Gửi yêu cầu"], "Mở đúng phiếu lương của mình, chọn Yêu cầu kiểm tra lại lương. Nhập khoản cần kiểm tra cùng lý do rồi Gửi yêu cầu; kiểm tra trạng thái Đang chờ phản hồi và tránh gửi trùng.");
guide("payroll.run.payslip.review-requests.list", payroll + "PayrollPayslipReviewPanel.tsx", ["Yêu cầu kiểm tra lại phiếu lương"], "Chọn đúng kỳ trong PAYROLL → Phiếu lương & phát hành, xem Yêu cầu kiểm tra lại phiếu lương. Đọc người gửi, nội dung và trạng thái; dùng Tải lại yêu cầu kiểm tra lương để lấy dữ liệu mới.");
guide("payroll.run.payslip.review-request.resolve", payroll + "PayrollPayslipReviewPanel.tsx", ["Gửi phản hồi", "Nội dung phản hồi"], "Mở đúng yêu cầu kiểm tra lại phiếu lương, chọn Phản hồi, nhập kết quả xử lý và Gửi phản hồi. Kiểm tra trạng thái Đã phản hồi; nếu cần thay đổi tiền lương, thực hiện quy trình điều chỉnh riêng.");
guide("api.get.8a6bcc27085077c3", payrollPage, ["getResults", "Ngày công"], "Chọn kỳ PAYROLL, xem bảng kết quả công theo nhân viên với Ngày công, Thiếu công và trạng thái khóa. Đối chiếu đúng tháng/chi nhánh; không tính lại lương nếu chỉ muốn tra cứu công.");
guide("payroll.adjustment.list", payrollPage, ["Chờ duyệt", "Điều chỉnh"], "Chọn kỳ PAYROLL → Chờ duyệt → Điều chỉnh, xem nhân viên, số tiền, lý do và trạng thái các khoản. Không duyệt hoặc từ chối khi chỉ tra cứu.");
guide("payroll.adjustment.create", payrollPage, ["Thêm khoản lương", "Loại điều chỉnh"], "Chọn kỳ, mở Thêm khoản lương, chọn nhân viên và loại Thưởng/Cộng thêm hoặc Khấu trừ/Phạt. Nhập số tiền và lý do rồi Lưu; kiểm tra khoản điều chỉnh chờ duyệt, chưa coi là đã áp dụng vào lương.");
guide("payroll.adjustment.approve", payrollPage, ["approveAdjustment"], "Trong Chờ duyệt → Điều chỉnh của đúng kỳ, đối chiếu nhân viên, số tiền và lý do rồi chọn duyệt khoản đó. Kiểm tra trạng thái đã duyệt; cập nhật bảng lương theo quy trình nếu cần phản ánh vào kết quả.");
guide("payroll.adjustment.reject", payrollPage, ["rejectAdjustment"], "Trong Chờ duyệt → Điều chỉnh, tìm đúng khoản không được chấp nhận và chọn từ chối. Kiểm tra trạng thái khoản; không tạo khoản âm để thay cho từ chối yêu cầu chưa duyệt.");
const explorer = "src/components/resource/FileExplorer.tsx";
guide("resource.trash.list", explorer, ["listTrash"], "Trong Tài nguyên → Tài liệu khác, chọn đúng không gian cá nhân/nhóm rồi mở Thùng rác. Xem các mục đã xóa; không chọn Khôi phục hoặc Xóa vĩnh viễn khi chỉ tra cứu.");
guide("api.get.5a8c34f32c006c0b", explorer, ["resourceService.breadcrumb"], "Mở Tài liệu khác, chọn đúng không gian và đi vào thư mục cần xem. Đọc thanh đường dẫn thư mục; chọn thư mục cha trên thanh để kiểm tra vị trí lưu.");
guide("api.post.f16467714880abd7", explorer, ["resourceService.uploadFile"], "Mở thư mục đích trong Tài liệu khác, chọn tải tệp từ máy và chọn đúng tệp. Chờ tải hoàn tất rồi kiểm tra tên tệp trong thư mục và mở xem nội dung; nếu tải lỗi, kiểm tra danh sách trước khi tải lại.");
guide("api.get.70715572be0f86f6", explorer, ["Chia sẻ tài nguyên", "getShares"], "Mở menu của đúng tệp hoặc thư mục → Chia sẻ. Đọc người/nhóm đang có quyền truy cập trong Chia sẻ tài nguyên; đóng hộp thoại nếu chỉ xem quyền.");
guide("api.patch.120dc3a54509fc0c", explorer, ["Đổi tên", "resourceService.rename"], "Mở menu của đúng mục → Đổi tên. Nhập tên mới, kiểm tra phần mở rộng tệp nếu có rồi xác nhận; đối chiếu tên mới trong đúng thư mục.");
guide("api.patch.1cfa9b644fbe938f", explorer, ["Di chuyển đến thư mục", "resourceService.move"], "Mở menu của đúng tệp/thư mục → Di chuyển đến thư mục. Chọn thư mục đích được phép truy cập, kiểm tra đường dẫn rồi xác nhận. Mở thư mục đích để kiểm tra mục đã chuyển; không tải bản sao thay cho di chuyển.");
guide("resource.restore", explorer, ["Khôi phục", "resourceService.restore"], "Mở Thùng rác trong đúng không gian, tìm mục và chọn Khôi phục. Quay lại danh sách tài liệu để kiểm tra vị trí và nội dung mục được phục hồi.");
guide("api.delete.771468fb212b7e25", explorer, ["Bỏ vào Thùng rác", "Xóa vĩnh viễn"], "Tìm đúng mục, mở menu xóa và đọc tên mục trong xác nhận. Với tài liệu đang dùng, chọn Bỏ vào Thùng rác; với mục đã ở Thùng rác, Xóa vĩnh viễn sẽ loại bỏ hẳn và chỉ dùng khi yêu cầu rõ ràng.", "Kiểm tra danh sách hoặc Thùng rác sau xử lý; không xác nhận xóa vĩnh viễn để thay thế việc đưa vào thùng rác.");
const marketing = "src/modules/marketing/";
guide("api.get.ddf0c072158be296", marketing + "pages/MarketingAutomationSettingsPage.tsx", ["Lưu cài đặt"], "Mở Cài đặt tự động, đọc trạng thái bật, kênh gửi và lịch của từng loại tin. Không đổi công tắc hoặc bấm Lưu cài đặt khi chỉ xem cấu hình.");
guide("marketing.holiday-campaign.list", marketing + "components/HolidayCampaignsSection.tsx", ["Chiến dịch lễ tết"], "Trong Cài đặt tự động → Chiến dịch lễ tết, xem tên, lịch chạy, nhóm khách hàng và trạng thái Đang bật/Đang tắt của từng chiến dịch.");
guide("marketing.holiday-campaign.create-draft", marketing + "components/HolidayCampaignsSection.tsx", ["Tên dịp (VD: Tết Nguyên Đán)"], "Trong Chiến dịch lễ tết, điền tên dịp, ngày chạy, tiêu đề và nội dung email; chọn hạng khách hàng khi cần giới hạn người nhận. Kiểm tra đối tượng và nội dung rồi gửi biểu mẫu tạo.", "Xem lại chiến dịch và trạng thái bật/tắt. Nếu yêu cầu chỉ tạo bản nháp, giữ chiến dịch ở trạng thái tắt; không kích hoạt gửi khi chưa được yêu cầu.");
guide("marketing.holiday-campaign.enabled.update", marketing + "components/HolidayCampaignsSection.tsx", ["Đang bật", "Đang tắt"], "Trong Chiến dịch lễ tết, tìm đúng chiến dịch, kiểm tra ngày chạy và nhóm khách hàng. Dùng công tắc để chuyển sang Đang bật hoặc Đang tắt đúng yêu cầu; tải lại và kiểm tra trạng thái đã lưu.");
guide("marketing.holiday-campaign.delete", marketing + "components/HolidayCampaignsSection.tsx", ["remove(campaign)"], "Tìm đúng chiến dịch lễ tết, dùng nút xóa trên dòng và đọc xác nhận nếu xuất hiện. Chỉ xóa khi muốn loại bỏ chiến dịch, không dùng xóa thay tạm tắt; tải lại danh sách để kiểm tra.");
guide("api.get.34a8d9d0814701f9", marketing + "pages/MarketingDeliveriesPage.tsx", ["Tất cả loại tin", "Tất cả trạng thái"], "Mở Nhật ký gửi, lọc loại tin và trạng thái Đã gửi/Lỗi/Bỏ qua. Chọn Tải lại, đối chiếu người nhận, thời điểm và nguyên nhân lỗi; không bấm thử gửi lại nếu chỉ tra cứu.");
const settlement = "src/modules/worker-management/partners/components/LaborPartnerSettlementsPanel.tsx";
guide("worker.partner.settlement.calculate", settlement, ["Tính / mở kỳ đối soát"], "Trong Đối tác lao động → Đối soát, chọn đối tác và tháng tính hoa hồng. Kiểm tra nguồn giới thiệu, nhập số tháng hoặc số giờ của từng lao động đúng cơ chế, rồi chọn Tính / mở kỳ đối soát.", "Đọc cảnh báo và các dòng hoa hồng của kỳ. Nếu kỳ đã tồn tại, đối chiếu kỳ được mở lại; chưa duyệt hoặc chi trả khi chỉ yêu cầu tính.");
guide("api.post.4b815164a8bb4143", settlement, ["Hủy kỳ"], "Mở đúng kỳ đối soát chưa bị khóa bởi trạng thái không cho phép hủy, chọn Hủy kỳ và nhập lý do. Kiểm tra xác nhận; sau khi xử lý, đối chiếu trạng thái Đã hủy. Không hoàn tác khoản chi bằng cách hủy kỳ.");
guide("api.post.0137e041d2b60a80", settlement, ["Lý do điều chỉnh:", "Điều chỉnh đối tác"], "Mở chi tiết kỳ đối soát cần điều chỉnh, chọn thao tác điều chỉnh. Nhập số tiền dương để trả thêm hoặc âm để giảm trừ, lý do và ngày thuộc kỳ điều chỉnh.", "Xác nhận và kiểm tra kỳ điều chỉnh mới ở trạng thái chờ duyệt; thao tác không tự sửa các dòng đã duyệt hoặc tự chi tiền.");
guide("worker.partner.payout.reverse", settlement, ["Hoàn tác giao dịch chi trả này?", "Lịch sử chi trả"], "Mở kỳ đối soát → Lịch sử chi trả, tìm đúng giao dịch còn được hoàn tác. Chọn Hoàn tác, đối chiếu số tiền và xác nhận; kiểm tra lịch sử cùng số Còn phải trả sau xử lý.");
guide("api.get.51885b828100e376", customer + "components/CustomerList.tsx", ["Mã, tên, số điện thoại hoặc email"], "Trong danh sách khách hàng, nhập mã, tên, số điện thoại hoặc email vào ô Tìm khách hàng. Đọc các kết quả, đối chiếu số điện thoại/mã trước khi mở hồ sơ; đổi chi nhánh hoặc điều kiện lọc nếu không thấy khách.");
guide("customer.settings.get", customer + "CustomerWorkspace.tsx", ["Cài đặt khách hàng"], "Mở Cài đặt khách hàng, xem mã hạng, tên hạng và ngưỡng lãi gộp của từng hạng. Không chỉnh ngưỡng hoặc lưu khi chỉ tra cứu.");
guide("customer.settings.update", customer + "CustomerWorkspace.tsx", ["Lưu cài đặt phân hạng"], "Mở Cài đặt khách hàng bằng tài khoản có quyền quản lý. Sửa mã, tên hoặc ngưỡng hạng đúng yêu cầu; kiểm tra thứ tự và ngưỡng từng hạng.", "Chọn Lưu cài đặt phân hạng rồi mở lại để đối chiếu các giá trị đã lưu. Không xóa hạng nền của hệ thống.");
guide("api.delete.6b7e088799881047", chat, ["Giải tán nhóm", "Giải tán phòng chat"], "Mở thông tin đúng nhóm bằng tài khoản có quyền, chọn Giải tán nhóm. Đọc cảnh báo xóa vĩnh viễn lịch sử của mọi thành viên; chỉ chọn Giải tán khi thực sự muốn xóa cả phòng. Kiểm tra phòng không còn trong danh sách.");
guide("api.delete.2cad6a5af287c9ed", chat, ["Rời khỏi nhóm", "Rời phòng"], "Mở thông tin nhóm cần rời, chọn Rời khỏi nhóm. Kiểm tra tên phòng trong xác nhận rồi chọn Rời phòng; đối chiếu lại danh sách nhóm của mình.");
guide("chat.room.member.remove", chat, ["removeMember"], "Mở thông tin nhóm và danh sách thành viên bằng tài khoản quản lý. Tìm đúng người, chọn thao tác xóa thành viên và đọc xác nhận trước khi đồng ý. Kiểm tra người đó không còn trong danh sách; không dùng Giải tán nhóm.");
const legal = "src/modules/legal-reference/LegalReferencePage.tsx";
guide("legal.repository.status", legal, ["Tình trạng kho"], "Mở Văn bản pháp luật và đọc Tình trạng kho: số văn bản, trạng thái chỉ mục, hàng chờ rà soát và lần đồng bộ gần nhất. Nếu tải lỗi, dùng Thử lại; không chạy đồng bộ mới chỉ để xem trạng thái.");
guide("legal.repository.sync", legal, ["Đồng bộ VBPL ngay"], "Trong Văn bản pháp luật, kiểm tra nguồn đã cấu hình và không có lượt đang chạy. Nhập Số trang mỗi lượt rồi chọn Đồng bộ VBPL ngay.", "Theo dõi trạng thái và lần đồng bộ gần nhất; xem Hàng rà soát cho phiên bản mới. Dữ liệu tải về chưa đồng nghĩa đã được duyệt để trả lời.");
guide("legal.review.list", legal, ["Hàng rà soát"], "Chọn Rà soát trong Văn bản pháp luật. Đọc từng văn bản, phiên bản, loại thay đổi và quan hệ sửa đổi/hợp nhất; tải bản gốc để đối chiếu khi cần. Không xác nhận hoặc từ chối nếu chỉ xem danh sách.");
guide("legal.review.decision", legal, ["Tải bản gốc để đối chiếu", "Ngày áp dụng", "Từ chối"], "Trong Hàng rà soát, chọn đúng phiên bản và đối chiếu bản gốc với nội dung trích xuất. Nếu chưa lập chỉ mục, cập nhật nội dung đã kiểm tra trước; nhập Ngày áp dụng khi duyệt phiên bản mới.", "Chọn Xác nhận nếu nội dung hợp lệ hoặc Từ chối theo kết quả rà soát. Đọc thông báo và kiểm tra mục đã rời hàng chờ hoặc trạng thái đã đổi.");
guide("legal.document.search", legal, ["Nội dung cần tra cứu", "Tra cứu tại ngày"], "Chọn Tra cứu, nhập Nội dung cần tra cứu và Tra cứu tại ngày; chọn phạm vi, lĩnh vực hoặc cơ quan ban hành nếu cần. Bấm Tra cứu, đọc đoạn Điều/Khoản/Điểm và mở văn bản nguồn để đối chiếu hiệu lực.");
guide("legal.document.answer", legal, ["Trả lời có trích dẫn"], "Trong Tra cứu, nhập câu hỏi, ngày áp dụng và bộ lọc phù hợp, chọn Trả lời có trích dẫn. Kiểm tra trích dẫn và hiệu lực văn bản nguồn; nếu không có nguồn phù hợp, không coi câu trả lời là căn cứ đã xác minh.");
const knowledge = "src/modules/marketing-suite/knowledge/pages/CompanyKnowledgePage.tsx";
const faq = "src/modules/marketing-suite/knowledge/components/knowledge/FaqLearningSuggestionsPanel.tsx";
guide("company-knowledge.account.list", knowledge, ["Facebook Page sử dụng tài liệu"], "Trong Kho tri thức, mở phạm vi sử dụng của một tài liệu hoặc biểu mẫu nạp tài liệu, xem danh sách Facebook Page sử dụng tài liệu. Đóng biểu mẫu khi chỉ tra cứu, không lưu thay đổi phạm vi.");
guide("company-knowledge.health company-knowledge.conflicts.list", knowledge, ["health?.documentsCount", "mâu thuẫn dữ liệu"], "Mở Kho tài liệu, đọc tổng số tài liệu và phần mâu thuẫn dữ liệu. Đối chiếu hai nguồn được nêu, loại mâu thuẫn và giá trị khác nhau; mở nguồn để kiểm tra. Không xóa tài liệu khi chỉ xem tình trạng kho.");
guide("company-knowledge.test-search", knowledge, ["Thử nghiệm tìm kiếm tri thức", "Kiểm tra"], "Mở phần thử nghiệm tìm kiếm tri thức, nhập câu hỏi đại diện cho nhu cầu khách hàng rồi chọn Kiểm tra. Đọc các đoạn được tìm thấy, mức khớp và câu trả lời mẫu; đối chiếu nguồn. Đây là thử nghiệm, không phải gửi phản hồi cho khách thật.");
guide("company-knowledge.documents.scopes.update", knowledge, ["Phạm vi sử dụng", "Chỉ Page được chọn"], "Tìm đúng tài liệu, chọn Phạm vi sử dụng. Chọn nghiệp vụ, kênh và Đồng bộ cho mọi Page hoặc Chỉ Page được chọn; nếu giới hạn Page, chọn ít nhất một Page.", "Kiểm tra phạm vi rồi chọn Lưu. Mở lại tài liệu để đối chiếu các kênh và Page đã áp dụng.");
guide("company-knowledge.faq-candidates.list", faq, ["Chờ duyệt", "Đã đưa vào Kho"], "Mở Đề xuất Câu hỏi Thường gặp, lọc Chờ duyệt, Đã đưa vào Kho hoặc Đã bỏ qua. Đọc câu hỏi và câu trả lời đề xuất, không duyệt khi chỉ tra cứu.");
guide("company-knowledge.faq-candidates.analyze", faq, ["Quét tin nhắn mới"], "Trong Đề xuất Câu hỏi Thường gặp, chọn Quét tin nhắn mới và chờ quét hoàn tất. Kiểm tra danh sách Chờ duyệt; kết quả là đề xuất, chưa tự động được coi là nội dung chuẩn trong kho.");
guide("company-knowledge.faq-candidate.approve", faq, ["Duyệt vào Kho Tri Thức", "Lưu & Duyệt vào Kho"], "Tìm đúng đề xuất đang chờ, đọc câu hỏi và đối chiếu câu trả lời với chính sách doanh nghiệp. Nếu cần sửa, chọn Sửa câu trả lời và nhập nội dung đúng.", "Chọn Duyệt vào Kho Tri Thức hoặc Lưu & Duyệt vào Kho khi đang sửa. Kiểm tra mục chuyển sang Đã đưa vào Kho.");
guide("company-knowledge.faq-candidate.reject", faq, ["Bỏ qua"], "Tìm đúng đề xuất chưa phù hợp, chọn Bỏ qua. Kiểm tra mục trong Đã bỏ qua; không dùng Xóa vĩnh viễn nếu chỉ muốn từ chối đề xuất.");
guide("company-knowledge.faq-candidate.delete", faq, ["Xóa vĩnh viễn"], "Mở đúng đề xuất FAQ, chọn Xóa vĩnh viễn, đọc xác nhận rồi đồng ý nếu muốn loại bỏ hẳn đề xuất. Tải lại danh sách để kiểm tra mục đã biến mất.");
guide("company-knowledge.page-chat.simulate", "src/modules/marketing-suite/knowledge/components/knowledge/PageChatSimulator.tsx", ["Gửi thử", "Nhập tin nhắn của khách…"], "Mở Mô phỏng chat Page, tạo hoặc chọn cuộc thử nghiệm, kiểm tra chế độ và Page được chọn. Nhập tin nhắn khách mẫu rồi dùng Gửi thử; đọc phản hồi trong cuộc mô phỏng. Không nhầm với gửi tin trong hội thoại khách hàng thật.");
guide("customer.transactions customer.transaction.detail", customer + "components/CustomerDetailPage.tsx", ["Lịch sử giao dịch"],
  "Tìm khách hàng theo tên hoặc số điện thoại, mở hồ sơ → Lịch sử giao dịch. Chọn khoảng thời gian và loại giao dịch cần xem.",
  "Đọc mã chứng từ, ngày, số tiền và trạng thái; mở dòng giao dịch để xem chi tiết. Kiểm tra đúng khách hàng và chi nhánh, không tạo chứng từ mới khi chỉ tra cứu.");
guide("api.get.c739a754761eb2a2", customer + "components/CustomerDetailPage.tsx", ["Mua hàng & bảo hành"], "Mở hồ sơ khách hàng → Mua hàng & bảo hành. Đối chiếu đơn hàng, giá trị mua và thiết bị IMEI/serial; kiểm tra thời hạn bảo hành của đúng thiết bị.");
guide("api.get.0e86266c268fecac", customer + "components/CustomerDetailPage.tsx", ["Dịch vụ & bảo hành"], "Mở hồ sơ khách hàng → Dịch vụ & bảo hành. Xem các phiếu sửa chữa, thiết bị, trạng thái và lịch sử dịch vụ của đúng khách hàng.");
guide("customer.activate", customer + "components/CustomerDetailPage.tsx", ["Kích hoạt lại"], "Mở đúng hồ sơ đang ngừng hoạt động, chọn Kích hoạt lại. Đọc xác nhận nếu xuất hiện; sau khi xử lý, tải lại hồ sơ và kiểm tra trạng thái Đang hoạt động.");
guide("customer.deactivate", customer + "components/CustomerDetailPage.tsx", ["Ngừng hoạt động"], "Mở đúng hồ sơ khách hàng, chọn Ngừng hoạt động. Kiểm tra khách hàng và nội dung xác nhận trước khi đồng ý; mở lại hồ sơ để đối chiếu trạng thái. Không xóa hồ sơ để thay thế việc ngừng hoạt động.");
guide("customer.billing.profile.list", customer + "components/BillingProfilesPanel.tsx", ["Hồ sơ xuất VAT"], "Mở hồ sơ khách hàng → Hồ sơ VAT. Đọc tên pháp nhân, mã số thuế, địa chỉ và email hóa đơn; phân biệt hồ sơ mặc định với các hồ sơ còn lại.");
guide("customer.billing.profile.create", customer + "components/BillingProfilesPanel.tsx", ["Thêm hồ sơ VAT", "Tên pháp nhân"], "Trong hồ sơ khách hàng → Hồ sơ VAT, chọn Thêm hồ sơ VAT. Điền tên pháp nhân, mã số thuế, địa chỉ hóa đơn, email và người liên hệ theo biểu mẫu.", "Kiểm tra thông tin pháp nhân rồi lưu biểu mẫu. Xem hồ sơ vừa thêm trong danh sách; nếu thông báo đã thêm nhưng tải lại thất bại, tải lại danh sách trước khi tạo lại.");
guide("api.post.383280e18fd7151d", chat, ["Ghim cuộc trò chuyện lên đầu", "Bỏ ghim cuộc trò chuyện này"], "Mở đúng cuộc trò chuyện, dùng nút Ghim cuộc trò chuyện lên đầu ở đầu khung chat; nếu đang ghim, dùng Bỏ ghim cuộc trò chuyện này. Kiểm tra vị trí cuộc trò chuyện trong danh sách; thao tác này khác ghim một tin nhắn.");
guide("chat.room.members.list", chat, ["Thêm thành viên vào nhóm"], "Mở phòng trò chuyện cần xem, mở thông tin nhóm và phần thành viên. Đọc danh sách người tham gia cùng vai trò Trưởng phòng, Phó phòng hoặc thành viên; không thay đổi thành viên khi chỉ tra cứu.");
guide("api.patch.d4060a45017e2ff2", chat, ["Lưu tên nhóm", "Chỉ Trưởng/Phó phòng nhắn tin"], "Mở thông tin nhóm bằng tài khoản có quyền quản lý. Sửa Tên nhóm rồi chọn Lưu tên nhóm; nếu yêu cầu đổi quyền nhắn tin, thay đổi đúng tùy chọn Chỉ Trưởng/Phó phòng nhắn tin.", "Mở lại thông tin nhóm để kiểm tra tên và quyền đã đổi. Mỗi tùy chọn có thể lưu riêng; không thay đổi các tùy chọn ngoài yêu cầu.");
guide("api.post.15ba51d677614349", chat, ["Thêm thành viên vào nhóm", "handleAddMembers"], "Mở thông tin nhóm → Thêm thành viên vào nhóm. Tìm và đánh dấu đúng người cần thêm, kiểm tra danh sách lựa chọn rồi xác nhận thêm. Xem lại thành viên trong nhóm để tránh thêm nhầm người.");
guide("chat.room.member.role.update", chat, ["Bổ nhiệm Phó phòng", "Bãi nhiệm Phó phòng"], "Trong danh sách thành viên nhóm, tìm đúng người. Chọn Thăng cấp làm Phó phòng hoặc Hạ cấp xuống Thành viên thường theo yêu cầu, đọc xác nhận và đồng ý. Đối chiếu vai trò mới bên cạnh tên người đó.");
guide("api.post.d63432efae84cbc1", chat, ["internalChatService.markAsRead"], "Mở đúng phòng trò chuyện để tải và đọc các tin nhắn. Ứng dụng tự đánh dấu đã đọc khi mở phòng; kiểm tra số tin chưa đọc trên danh sách. Không gửi tin nhắn chỉ để đánh dấu đã đọc.");
guide("api.post.42aabe336dd32361", chat, ["Ghim tin nhắn"], "Mở phòng, tìm đúng tin nhắn rồi chọn Ghim tin nhắn trong nhóm thao tác của tin đó. Kiểm tra tin xuất hiện ở phần ghim của phòng; không dùng nút ghim cuộc trò chuyện.");
guide("api.post.98ca589fbd77b8d0", chat, ["Bỏ ghim tin nhắn này"], "Trong phòng chat, tìm tin đang ghim và chọn Bỏ ghim tin nhắn này. Kiểm tra tin đã rời khu vực ghim nhưng vẫn còn trong lịch sử trò chuyện.");
guide("api.post.37d3c6ae92576f7d", chat, ["reactToMessage"], "Tìm đúng tin nhắn trong phòng, mở bảng cảm xúc và chọn biểu tượng. Kiểm tra biểu tượng xuất hiện dưới tin; chọn lại cùng cảm xúc của mình để gỡ nếu đó là yêu cầu.");
guide("api.delete.405c62abccc22d73", chat, ["Thu hồi tin nhắn"], "Mở phòng, tìm chính xác tin cần thu hồi, chọn Thu hồi tin nhắn. Đọc xác nhận và chọn Thu hồi khi đúng nội dung; kiểm tra trạng thái tin sau khi xử lý. Chỉ thực hiện với tin mà tài khoản được phép thu hồi.");
